if (pm.response.code === 200) {
    const lista = pm.response.json();
    const claves = ["recordatorioId", "recordatorioMananaId", "recordatorioAyerId"];
    const valores = Object.fromEntries(claves.map(clave => [clave, pm.variables.get(clave)]));
    const uuid = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
    pm.test("Preparación: IDs de hoy, mañana y ayer disponibles", function () {
        for (const clave of claves) {
            pm.expect(valores[clave], "Falta " + clave + ": ejecutar 03-03 a 03-05 o cargar el UUID correspondiente; revisar colección, entorno y variables locales").to.match(uuid);
        }
    });
    pm.test("Todos los resultados corresponden al día argentino actual", function () {
        const diaArgentino = fecha => new Date(new Date(fecha).getTime() - 3 * 3600000).toISOString().slice(0, 10);
        const hoy = diaArgentino(new Date());
        pm.expect(lista).to.be.an("array");
        for (const r of lista) pm.expect(diaArgentino(r.fechaHoraInicio), "Fecha de " + r.idRecordatorio).to.eql(hoy);
    });
    pm.test("No devuelve recordatorios inactivos", function () {
        for (const r of lista) pm.expect(r.estado).not.to.eql("INACTIVO");
    });
    if (claves.every(clave => uuid.test(valores[clave] || ""))) {
        const ids = lista.map(r => r.idRecordatorio);
        pm.test("Incluye hoy y excluye ayer/mañana", function () {
            pm.expect(ids).to.include(valores.recordatorioId);
            pm.expect(ids).not.to.include(valores.recordatorioMananaId);
            pm.expect(ids).not.to.include(valores.recordatorioAyerId);
        });
    }
}
